insert into public.nha_todo_meta (id,data) values ('nha:goals', $g${"note": "カレンダーにも詳細スケジュールを登録済み。必ずカレンダーと合わせて確認する。", "month": "2026-06", "annual": "車両管理・補修・美化の仕組みを整え、店舗の運用品質と安全性を上げる。", "monthlyTarget": "7月以降に向けて、車両管理・環境整備・安全対策の土台を6月中に整える。"}$g$::jsonb)
  on conflict (id) do update set data=excluded.data, updated_at=now();
